int cipso_v4_doi_add_common(struct genl_info *info, struct cipso_v4_doi *doi_def)
{
    struct nlattr *attr;
    int i, count, max_tags = CIPSO_V4_MAX_TAGS;
    int tag_idx = 0;

    attr = info->attrs[CIPSO_V4_ATTR_TAGS];
    if (!attr)
        return -EINVAL;

    count = nla_len(attr) / sizeof(__u32);
    if (count > max_tags)
        return -EINVAL;

    while (tag_idx < max_tags) {
        if (tag_idx < count)
            doi_def->tags[tag_idx] = nla_get_u32(nla_data(attr) + (tag_idx * sizeof(__u32)));
        else
            doi_def->tags[tag_idx] = CIPSO_V4_TAG_INVALID;

        tag_idx++;
    }

    return 0;
}

int cipso_v4_doi_add_common_attrs(struct genl_info *info, struct cipso_v4_doi *doi_def)
