    if (!attr) {
        return -EINVAL;
    }

    struct nlattr *tags[NLMSG_DEFAULT_SIZE];
    int rem;
    nla_for_each_attr(attr, info->attrs[ATTR_CIPSO_TAGS], rem) {
        if (tag_count >= CIPSO_V4_TAG_MAX) {
