int cipso_v4_doi_add_common(struct genl_info *info, struct cipso_v4_doi *doi_def)
{
    struct nlattr *attr;
    int tag_count = 0;
    int i;

    attr = nla_find(info->attrs, genlmsg_attrlen(info->snd_portid, 0), CIPSO_ATTR_TAGS);
    if (!attr)
        return -EINVAL;

    if (nla_len(attr) % sizeof(u16) != 0)
        return -EINVAL;

    tag_count = nla_len(attr) / sizeof(u16);
    if (tag_count > CIPSO_V4_MAX_TAGS)
        return -EINVAL;

    for (i = 0; i < tag_count; i++) {
        u16 tag = *(__be16 *)nla_data(attr) + i;
        doi_def->tags[i] = be16_to_cpu(tag);
    }

    for (; i < CIPSO_V4_MAX_TAGS; i++)
        doi_def->tags[i] = CIPSO_V4_TAG_INVALID;

    return 0;
}
